class AsyncPublic:
    """Profile `public`: the operations its cut holds. `from_env()` reads `INORBIT_TOKEN`, or `INORBIT_KEY_ID`, `INORBIT_KEY_SECRET` and `INORBIT_SCOPES`."""

    profile: ClassVar[str] = "public"
    """The profile's name."""
    accounts: AsyncPublicAccounts
    """The `accounts` operations."""
    agents: AsyncPublicAgents
    """The `agents` operations."""
    connections: AsyncPublicConnections
    """The `connections` operations."""
    events: AsyncPublicEvents
    """The `events` operations."""
    extensions: AsyncPublicExtensions
    """The `extensions` operations."""
    radar: AsyncPublicRadar
    """The `radar` operations."""
    rfcs: AsyncPublicRfcs
    """The `rfcs` operations."""
    trails: AsyncPublicTrails
    """The `trails` operations."""

    def __init__(self, client: AsyncClient) -> None:
        """The profile on a client built for its credential."""
        self.client = client
        self.accounts = AsyncPublicAccounts(client)
        self.agents = AsyncPublicAgents(client)
        self.connections = AsyncPublicConnections(client)
        self.events = AsyncPublicEvents(client)
        self.extensions = AsyncPublicExtensions(client)
        self.radar = AsyncPublicRadar(client)
        self.rfcs = AsyncPublicRfcs(client)
        self.trails = AsyncPublicTrails(client)

    @classmethod
    def from_env(cls) -> AsyncPublic:
        """The profile with its credential from the environment."""
        return cls(AsyncClient.from_env())

    @classmethod
    def load(cls, *, load_options: LoadOptions | None = None, **options: Unpack[AsyncClientOptions]) -> AsyncPublic:
        """The profile with its settings and credential from code, the environment, the config file and the `iohr` login."""
        return cls(AsyncClient.load(load_options=load_options, **options))

    async def me(self, *, timeout: float | None = None) -> Response[Me]:
        """`GET /v1/me`; needs scope `identity:read`. A key needs scope `identity:read`."""
        return await self.client.request(
            _ops.me(),
            Me,
            timeout=timeout,
        )


